B.ar4=new A.bm([B.b6,"Une r\xe9conciliation, une tendresse qui circule sans heurts.",B.b7,"Une gestion sage, des \xe9changes \xe9quilibr\xe9s.",B.b8,"La gu\xe9rison douce, l'\xe9quilibre des humeurs.",B.b9,"Un calme profond, une vie qui coule \xe0 son rythme."],t.Q)
