B.a82=new A.aN(59107,"MaterialIcons",!1)
B.ar3=new A.bm([B.b6,"Une attirance br\xfblante, magn\xe9tique\u2026 et peut-\xeatre dangereuse.",B.b7,"L'argent vient vite, mais il exige d'en payer le prix.",B.b8,"M\xe9fie-toi des exc\xe8s qui flattent le corps et l'usent.",B.b9,"Le plaisir intense, \xe0 vivre sans s'y encha\xeener."],t.Q)
