B.aqY=new A.bm([B.b6,"Un bonheur \xe0 deux rayonnant, une union heureuse.",B.b7,"La prosp\xe9rit\xe9, la reconnaissance, un projet qui rayonne.",B.b8,"Une sant\xe9 \xe9clatante, une \xe9nergie solaire.",B.b9,"La joie pure, simple, partag\xe9e au grand jour."],t.Q)
